using System.Formats.Asn1;
using System.Globalization;
using System.Security.Cryptography;

namespace Yubico.YubiKit.Core.Cryptography;

/// <summary>
/// A class that converts ASN.1 DER encoded X.509 SubjectPublicKeyInfo to instances of IPublicKey.
/// </summary>
/// <remarks>
/// AlgorithmIdentifier exhaustion is checked for supported algorithms. Outer SPKI, top-level, and
/// nested RSA-reader exhaustion are separate and are not all checked here. Point framing and component
/// widths do not establish full mathematical validity. Inputs remain borrowed and outputs own copies.
/// </remarks>
internal class AsnPublicKeyDecoder
{
    /// <summary>
    /// Creates an instance of <see cref="IPublicKey"/> from a
    /// ASN.1 DER-encoded SubjectPublicKeyInfo.
    /// </summary>
    /// <param name="subjectPublicKeyInfo">
    /// The ASN.1 DER-encoded SubjectPublicKeyInfo.
    /// </param>
    /// <returns>
    /// A new instance of <see cref="IPublicKey"/>.
    /// </returns>
    /// <exception cref="CryptographicException">Thrown if public key does not match expected format.</exception>
    /// <exception cref="AsnContentException">The ASN.1 structure or algorithm parameters are malformed.</exception>
    /// <exception cref="NotSupportedException">The algorithm or named curve is not modeled.</exception>
    public static IPublicKey CreatePublicKey(ReadOnlyMemory<byte> subjectPublicKeyInfo)
    {
        var reader = new AsnReader(subjectPublicKeyInfo, AsnEncodingRules.DER);
        var seqSubjectPublicKeyInfo = reader.ReadSequence();
        var seqAlgorithmIdentifier = seqSubjectPublicKeyInfo.ReadSequence();

        var keyAlgorithmOid = seqAlgorithmIdentifier.ReadObjectIdentifier();
        var subjectPublicKey = seqSubjectPublicKeyInfo.ReadBitString(out var unusedBitCount);
        if (unusedBitCount != 0)
        {
            throw new CryptographicException("Invalid subject public key encoding");
        }

        if (keyAlgorithmOid == Oids.Rsa && seqAlgorithmIdentifier.HasData)
        {
            // RFC 8017 specifies NULL; preserve the existing absent-parameter input tolerance.
            seqAlgorithmIdentifier.ReadNull();
        }

        // RFC 5480: one named-curve OID. RFC 8410: Ed/X parameters MUST be absent.
        var curveOid = keyAlgorithmOid == Oids.EcPublicKey ? seqAlgorithmIdentifier.ReadObjectIdentifier() : string.Empty;

        IPublicKey publicKey = keyAlgorithmOid switch
        {
            Oids.Rsa => CreateRSAPublicKey(subjectPublicKey),
            Oids.EcPublicKey => CreateECPublicKey(curveOid, subjectPublicKey),
            Oids.X25519 => Curve25519PublicKey.CreateFromValue(subjectPublicKey, KeyType.X25519),
            Oids.Ed25519 => Curve25519PublicKey.CreateFromValue(subjectPublicKey, KeyType.Ed25519),
            _ => throw new NotSupportedException($"Unsupported public key algorithm OID '{keyAlgorithmOid}'.")
        };

        // Enforce parameter rules only for supported algorithms, preserving the unsupported-OID exception.
        seqAlgorithmIdentifier.ThrowIfNotEmpty();
        return publicKey;
    }

    private static RSAPublicKey CreateRSAPublicKey(byte[] subjectPublicKey)
    {
        var subjectPublicKeyReader = new AsnReader(subjectPublicKey, AsnEncodingRules.DER);
        var seqSubjectPublicKey = subjectPublicKeyReader.ReadSequence();
        var modulusBigInt = seqSubjectPublicKey.ReadIntegerBytes();
        var exponentBigInt = seqSubjectPublicKey.ReadIntegerBytes();

        seqSubjectPublicKey.ThrowIfNotEmpty();

        var modulus = AsnUtilities.TrimLeadingZeroes(modulusBigInt.Span);
        var exponent = AsnUtilities.TrimLeadingZeroes(exponentBigInt.Span);
        var rsaParameters = new RSAParameters
        {
            Modulus = modulus.ToArray(),
            Exponent = exponent.ToArray()
        };

        return RSAPublicKey.CreateFromParameters(rsaParameters);
    }

    private static ECPublicKey CreateECPublicKey(string curveOid, byte[] subjectPublicKey)
    {
        if (!CryptographicDefinitions.Curves.TryGetByOid(curveOid, out var curveInfo)
            || curveInfo.Form != CurveForm.ShortWeierstrass)
        {
            throw new NotSupportedException(
                string.Format(
                    CultureInfo.CurrentCulture,
                    "Unsupported EC curve OID '{0}'.",
                    curveOid));
        }

        // For PKCS EC keys, the bit string contains the EC point in uncompressed form:
        // 0x04 || X coordinate || Y coordinate.
        AsnUtilities.ValidateDecodedEcPoint(subjectPublicKey, curveOid);

        var coordinateLengthBytes = AsnUtilities.GetDecodedCoordinateLengthBytes(curveOid);
        var xCoordinate = new byte[coordinateLengthBytes];
        var yCoordinate = new byte[coordinateLengthBytes];

        // Skip the first byte (0x04 indicating uncompressed point)
        Buffer.BlockCopy(subjectPublicKey, 1, xCoordinate, 0, coordinateLengthBytes);
        Buffer.BlockCopy(subjectPublicKey, 1 + coordinateLengthBytes, yCoordinate, 0, coordinateLengthBytes);

        var curve = ECCurve.CreateFromValue(curveOid);
        var ecParams = new ECParameters
        {
            Curve = curve,
            Q = new ECPoint
            {
                X = xCoordinate,
                Y = yCoordinate
            }
        };

        return ECPublicKey.CreateFromParameters(ecParams);
    }
}

