    {
        var dataBytes = dataToMac.ToArray();

        try
        {
            if (NativeMethods.CmacEvpMacUpdate(_cmacCtx, dataBytes, dataBytes.Length) == 0)
                throw new SecurityException("ExceptionMessages.CmacFailed");
