            Cla = 0,
            Ins = InsGetDeviceInfo,
            P1 = page,
            P2 = 0
        };

        var response = await protocol.TransmitAndReceiveAsync(apdu, cancellationToken: cancellationToken)
            .ConfigureAwait(false);
