        if (mac.Length != 16) throw new ArgumentException("MAC key must be 16 bytes", nameof(mac));
        if (dek.Length is not 0 and not 16)
            throw new ArgumentException("DEK must be 16 bytes if provided", nameof(dek));

        _enc = enc.ToArray();
        _mac = mac.ToArray();
        _dek = dek.Length == 16 ? dek.ToArray() : null;
    }

    /// <summary>
    ///     Gets the static encryption key.
    /// </summary>
    public ReadOnlySpan<byte> Enc => _enc;

    /// <summary>
    ///     Gets the static MAC key.
    /// </summary>
    public ReadOnlySpan<byte> Mac => _mac;

    /// <summary>
    ///     Gets the static DEK (Data Encryption Key), if available.
    /// </summary>
    public ReadOnlySpan<byte> Dek => _dek;


    /// <summary>
    ///     Zeroes this instance's owned key arrays, leaving caller source storage unchanged.
    /// </summary>
