        context.CopyTo(derivationData[(DerivationDataPrefixLength + 5)..]);

        using ICmacPrimitives cmac = CryptographyProviders.CmacPrimitivesCreator(CmacBlockCipherAlgorithm.Aes128);
        cmac.CmacInit(key);
        cmac.CmacUpdate(derivationData);
        var mac = new byte[16];
