{
    private IOtpHidProtocol OtpProtocol =>
        (IOtpHidProtocol)(Protocol ?? throw new ObjectDisposedException(nameof(RawOtpHidSession)));

    private RawOtpHidSession(IOtpHidConnection connection)
        : base(connection)
    {
    }

