    {
        if (_disposed) return;

        CryptographicOperations.ZeroMemory(_bytes);
        Length = 0;
        Tag = 0;
        _disposed = true;
    }


    private void Encode(ReadOnlySpan<byte> value)
    {
        var tagByteCount = GetMinimalByteCount((uint)Tag);
