            buffer = buffer[1..]; // Skip the tag byte
        }

        if (buffer.Length < 1) throw new ArgumentException("Insufficient data for length");

        // Read the length of the TLV value.
        int length = buffer[0];
        buffer = buffer[1..];

        // BER-TLV: 0x80 = indefinite length (not supported in determinate-length encoding)
        if (length == 0x80)
        {
            throw new ArgumentException("Indefinite length encoding (0x80) is not supported");
        }

        // Long form (X.690 §8.1.3.5): bits 7..1 give the number of subsequent length octets, which
        // encode an unsigned big-endian length. 0xFF is reserved. Redundant leading zero octets are
