            var deviceInfo = await mgmt.GetDeviceInfoAsync();

            // Compare the freshly decoded PIV approval flag; no approved operation is exercised.
            Assert.True((deviceInfo.FipsApproved & DeviceCapabilities.Piv) != 0);
        });
    }

