        var raw = await EnumerateRawUsbInterfacesAsync();
        Assert.NotEmpty(raw);

        var devices = await TransientScanRetry.ScanAsync(
            () => YubiKeyManager.FindAllAsync());

        foreach (var type in ConcreteTypes)
        {
            var enumerated = raw.Count(i => i.Type == type);
