                    var move = firstMove;
                    while (await move)
                    {
                        var evt = enumerator.Current;
                        Note($"CHANGE {evt}");
                        if (evt is DeviceRemoved removed)
                            removedTcs.TrySetResult(removed.Device);
                        else if (evt is DeviceAdded added)
                            Arrival(added.Device).TrySetResult();

