        (byte[] derivedPk, byte[] arkgKeyHandle) = primitives.Derive(PkBl, PkKem, IkmA, CtxA);

        Assert.Equal(ExpectedDerivedA, derivedPk);
        Assert.Equal(ExpectedHandleA, arkgKeyHandle);
    }

    [Fact]
    public void DerivePublicKey_DifferentIkm_ProducesDifferentKeys()
    {
        IArkgPrimitives primitives = CryptographyProviders.ArkgPrimitivesCreator();

        (byte[] derivedA, _) = primitives.Derive(PkBl, PkKem, IkmA, CtxA);
        (byte[] derivedB, _) = primitives.Derive(PkBl, PkKem, IkmB, CtxA);

        Assert.NotEqual(derivedA, derivedB);
        Assert.Equal(ExpectedDerivedA, derivedA);
        Assert.Equal(ExpectedDerivedB, derivedB);
