    [Fact]
    public void DerivePublicKey_DifferentCtx_ProducesDifferentKeys()
    {
        IArkgPrimitives primitives = CryptographyProviders.ArkgPrimitivesCreator();

        (byte[] derivedA, _) = primitives.Derive(PkBl, PkKem, IkmA, CtxA);
