        // interface falls out as its own single-interface key.
        var merged = CompositeDeviceMerger.Merge([
            Usb("pcsc:cc", ConnectionType.SmartCard, FullKeyPid, serial: 103),
            Usb("pcsc:cc", ConnectionType.SmartCard, FullKeyPid, serial: 103),
