        var keyB1 = Assert.Single(scan1, d => d.DeviceId == "ykphysical:222");
        Assert.Contains(
            Assert.IsType<YubiKeyDevice>(keyB1).InterfaceIds,
            id => id.EndsWith(OtpB, StringComparison.Ordinal));

