        Assert.Equal(2, scan2.Count);
        Assert.All(scan2, d => Assert.Equal(Dual, d.AvailableConnections));
        Assert.Contains(scan2, d => d.DeviceId == "ykphysical:111");
        Assert.Contains(scan2, d => d.DeviceId == "ykphysical:222");

