    [Fact]
    [Trait("Category", "RuntimeResilience")]
    public async Task SendCommandAsync_WhenCallbackAndTerminalValidationFail_PreservesProtocolErrorAndLogsCallback()
    {
        var connection = new FakeFidoHidConnection();
        var logger = new RecordingLogger();
        var protocol = new FidoHidProtocol(connection, logger);
        const string marker = "ISC56-callback-credential-sentinel";
        var promptFailure = new ArgumentException($"prompt failed with {marker}");
        var prompt = new RecordingUserPresencePrompt(promptFailure);
        connection.QueueResponsePackets(
            CreateInitPacket(TestChannelId, CtapConstants.CtapHidKeepAlive, [KeepAliveUpNeeded]),
            CreateInitPacket(TestChannelId, CtapConstants.CtapHidInit, [0xAA]));

        InvalidOperationException actual = await Assert.ThrowsAsync<InvalidOperationException>(() =>
            protocol.SendCommandAsync(
                CtapConstants.CtapVendorFirst,
                ReadOnlyMemory<byte>.Empty,
                CreateUserPresenceNotification(prompt),
                TestContext.Current.CancellationToken));

        Assert.Contains("does not match request command", actual.Message, StringComparison.Ordinal);
        Assert.NotEmpty(logger.Events);
        Assert.Contains(logger.Events, entry => entry.Contains("User-presence callback failed before CTAP HID terminal response validation also failed", StringComparison.Ordinal));
        Assert.Contains(logger.Events, entry => entry == $"ExceptionType={typeof(ArgumentException).FullName}");
        Assert.DoesNotContain(logger.Events, entry => entry == $"ExceptionType={typeof(InvalidOperationException).FullName}");
        Assert.DoesNotContain(logger.Events, entry => entry.Contains(marker, StringComparison.Ordinal));
        Assert.DoesNotContain(logger.Exceptions, exception => exception is not null);
    }

    /// <summary>
    /// Checks that a multi-packet vendor response is drained before surfacing cancellation. The later
    /// scripted exchange must receive its own bytes rather than the original response's continuation.
    /// </summary>
    [Fact]
    [Trait("Category", "RuntimeResilience")]
    public async Task SendCommandAsync_AbandonedWhenAnswerIsMultiPacket_DrainsEveryFrame()
    {
        var connection = new FakeFidoHidConnection();
        var protocol = new FidoHidProtocol(connection);
        using var cts = new CancellationTokenSource();

        var racedPayload = new byte[CtapConstants.InitDataSize + 20];
        racedPayload.AsSpan().Fill(0x5A);

        connection.QueueResponsePackets(
            CreateInitPacket(TestChannelId, CtapConstants.CtapHidKeepAlive, [KeepAliveUpNeeded]),
            CreateInitPacket(TestChannelId, CtapConstants.CtapVendorFirst, racedPayload),
            CreateContinuationPacket(TestChannelId, sequence: 0, racedPayload.AsSpan(CtapConstants.InitDataSize)));

        connection.OnResponseDequeued = packet =>
        {
            if (IsCommand(packet, CtapConstants.CtapHidKeepAlive))
                cts.Cancel();
        };

        await Assert.ThrowsAnyAsync<OperationCanceledException>(() =>
            protocol.SendCommandAsync(
                CtapConstants.CtapVendorFirst,
                ReadOnlyMemory<byte>.Empty,
                cancellationToken: cts.Token));

        // The continuation frame was consumed, so the next exchange sees its own response rather
        // than the tail of the abandoned one.
        connection.OnResponseDequeued = null;
        connection.QueueResponsePackets(
            CreateInitPacket(TestChannelId, CtapConstants.CtapVendorFirst, [0xAA]));

        var afterCancel = await protocol.SendCommandAsync(
            CtapConstants.CtapVendorFirst,
            ReadOnlyMemory<byte>.Empty,
            cancellationToken: TestContext.Current.CancellationToken);

        Assert.Equal(1, afterCancel.Length);
        Assert.Equal(0xAA, afterCancel.Span[0]);
    }

    /// <summary>
    /// Checks the SDK's policy of returning a scripted CBOR success that races caller cancellation.
    /// CTAP 2.3 Proposed Standard (February 26, 2026), §11.2.9.1.5 requires the authenticator to return
    /// KEEPALIVE_CANCEL for canceled CBOR work and forbids a reply to CANCEL itself. Returning the raced
    /// success here is an SDK nonrollback policy, rather than a host requirement from that passage.
    /// </summary>
    [Fact]
    [Trait("Category", "RuntimeResilience")]
    [Trait("Audit", "YESDK-1617")]
    public async Task SendCommandAsync_CborAbandonedDuringKeepAlive_LateCtapSuccessIsReturned()
    {
        var connection = new FakeFidoHidConnection();
        var protocol = new FidoHidProtocol(connection);
        using var cts = new CancellationTokenSource();

        connection.QueueResponsePackets(
            CreateInitPacket(TestChannelId, CtapConstants.CtapHidKeepAlive, [KeepAliveUpNeeded]),
            CreateInitPacket(TestChannelId, CtapConstants.CtapHidCbor, [CtapConstants.CtapStatusSuccess, 0xA0]));
        connection.OnResponseDequeued = packet =>
        {
            if (IsCommand(packet, CtapConstants.CtapHidKeepAlive))
                cts.Cancel();
        };

        var response = await protocol.SendCommandAsync(
            CtapConstants.CtapHidCbor,
            ReadOnlyMemory<byte>.Empty,
            cancellationToken: cts.Token);

        Assert.Equal(new byte[] { CtapConstants.CtapStatusSuccess, 0xA0 }, response.ToArray());
        Assert.Equal(
            1,
            connection.SentPacketSnapshots.Count(packet => IsCommand(packet, CtapConstants.CtapHidCancel)));

        connection.OnResponseDequeued = null;
        connection.QueueResponsePackets(
            CreateInitPacket(TestChannelId, CtapConstants.CtapHidCbor, [CtapErrNoCredentials]));
        var afterCancel = await protocol.SendCommandAsync(
            CtapConstants.CtapHidCbor,
            ReadOnlyMemory<byte>.Empty,
            cancellationToken: TestContext.Current.CancellationToken);
        Assert.Equal(CtapErrNoCredentials, afterCancel.Span[0]);
    }

    /// <summary>Only a CTAP success survives the cancel; the 0x2D acknowledgement and any other status still cancel.</summary>
    [Theory]
    [InlineData(CtapErrKeepAliveCancel)]
    [InlineData(CtapErrNoCredentials)]
    [Trait("Category", "RuntimeResilience")]
    [Trait("Audit", "YESDK-1617")]
    public async Task SendCommandAsync_CborAbandonedDuringKeepAlive_NonSuccessStillCancels(byte status)
    {
        var connection = new FakeFidoHidConnection();
        var protocol = new FidoHidProtocol(connection);
        using var cts = new CancellationTokenSource();

        connection.QueueResponsePackets(
            CreateInitPacket(TestChannelId, CtapConstants.CtapHidKeepAlive, [KeepAliveUpNeeded]),
            CreateInitPacket(TestChannelId, CtapConstants.CtapHidCbor, [status]));
        connection.OnResponseDequeued = packet =>
        {
            if (IsCommand(packet, CtapConstants.CtapHidKeepAlive))
                cts.Cancel();
        };

        await Assert.ThrowsAnyAsync<OperationCanceledException>(() =>
            protocol.SendCommandAsync(
                CtapConstants.CtapHidCbor,
                ReadOnlyMemory<byte>.Empty,
                cancellationToken: cts.Token));

        Assert.Equal(
            1,
            connection.SentPacketSnapshots.Count(packet => IsCommand(packet, CtapConstants.CtapHidCancel)));

        connection.OnResponseDequeued = null;
        connection.QueueResponsePackets(
            CreateInitPacket(TestChannelId, CtapConstants.CtapHidCbor, [CtapConstants.CtapStatusSuccess]));
        var afterCancel = await protocol.SendCommandAsync(
            CtapConstants.CtapHidCbor,
            ReadOnlyMemory<byte>.Empty,
            cancellationToken: TestContext.Current.CancellationToken);
        Assert.Equal(CtapConstants.CtapStatusSuccess, afterCancel.Span[0]);
    }

    [Fact]
    [Trait("Category", "RuntimeResilience")]
    public async Task SendCommandAsync_NotAbandoned_DoesNotSendCtapHidCancel()
    {
        var connection = new FakeFidoHidConnection();
        var protocol = new FidoHidProtocol(connection);

        connection.QueueResponsePackets(
            CreateInitPacket(TestChannelId, CtapConstants.CtapHidKeepAlive, [KeepAliveUpNeeded]),
            CreateInitPacket(TestChannelId, CtapConstants.CtapVendorFirst, [0xAA]));

        var response = await protocol.SendCommandAsync(
            CtapConstants.CtapVendorFirst,
            ReadOnlyMemory<byte>.Empty,
            cancellationToken: TestContext.Current.CancellationToken);

        Assert.Equal(0xAA, response.Span[0]);
        Assert.DoesNotContain(
            connection.SentPacketSnapshots,
            packet => IsCommand(packet, CtapConstants.CtapHidCancel));
    }

    /// <summary>CTAP HID keep-alive status byte meaning a touch is awaited.</summary>
    private const byte KeepAliveUpNeeded = 0x02;
    private const byte CtapErrKeepAliveCancel = 0x2D; // CTAP2_ERR_KEEPALIVE_CANCEL
    private const byte CtapErrNoCredentials = 0x27;   // CTAP2_ERR_NO_CREDENTIALS
    private const uint TestChannelId = 0x01020304;

    private static UserPresenceContext CreateUserPresenceContext() => new()
    {
        Basis = UserPresenceBasis.PolicyRequires,
        Application = "FIDO2",
        Scope = "example.com"
    };

    private static UserPresenceNotification CreateUserPresenceNotification(IUserPresencePrompt prompt) =>
        UserPresenceNotification.Create(prompt, CreateUserPresenceContext());

    private static bool IsCommand(byte[] packet, byte command) =>
        (packet[4] & ~CtapConstants.InitPacketMask) == command;

    private static byte[] CreateInitPacket(uint channelId, byte command, ReadOnlySpan<byte> payload)
    {
        var packet = new byte[CtapConstants.PacketSize];
        BinaryPrimitives.WriteUInt32BigEndian(packet, channelId);
        packet[4] = (byte)(command | CtapConstants.InitPacketMask);
        packet[5] = (byte)(payload.Length >> 8);
        packet[6] = (byte)payload.Length;
        payload[..Math.Min(payload.Length, CtapConstants.InitDataSize)]
            .CopyTo(packet.AsSpan(CtapConstants.InitHeaderSize));
        return packet;
    }

    private static byte[] CreateContinuationPacket(uint channelId, byte sequence, ReadOnlySpan<byte> payload)
    {
        var packet = new byte[CtapConstants.PacketSize];
        BinaryPrimitives.WriteUInt32BigEndian(packet, channelId);
        packet[4] = sequence;
        payload[..Math.Min(payload.Length, CtapConstants.ContinuationDataSize)]
            .CopyTo(packet.AsSpan(CtapConstants.ContinuationHeaderSize));
        return packet;
    }

    private sealed class FakeFidoHidConnection : IFidoHidConnection, ITerminalWakeControl
    {
        private readonly Queue<byte[]> _responsePackets = new();
        private readonly TaskCompletionSource<ReadOnlyMemory<byte>> _heldRead =
            new(TaskCreationOptions.RunContinuationsAsynchronously);
        private byte[]? _lastInitRequest;
        private bool _initResponseSent;

        public int PacketSize => CtapConstants.PacketSize;

        public ConnectionType Type => ConnectionType.HidFido;

        public int InitRequestCount { get; private set; }
        public int TerminalWakeCount { get; private set; }
        public bool IsDisposed { get; private set; }
        public bool HoldNextReceive { get; set; }
        public TaskCompletionSource PendingReceive { get; } = new(TaskCreationOptions.RunContinuationsAsynchronously);
        public bool ThrowOnNextSend { get; set; }

        /// <summary>
        /// Invoked as each queued packet is handed to the protocol, letting a test act at a
        /// precise point mid-exchange — notably abandoning the caller while a keep-alive is
        /// being processed.
        /// </summary>
        public Action<byte[]>? OnResponseDequeued { get; set; }

        public List<ReadOnlyMemory<byte>> RetainedSentPackets { get; } = [];
        public List<byte[]> SentPacketSnapshots { get; } = [];

        public void QueueResponsePackets(params byte[][] packets)
        {
            foreach (var packet in packets)
            {
                _responsePackets.Enqueue(packet);
            }
        }

        public Task SendAsync(ReadOnlyMemory<byte> packet, CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();
            RetainedSentPackets.Add(packet);
            byte[] snapshot = packet.ToArray();
            SentPacketSnapshots.Add(snapshot);
            if ((snapshot[4] & ~CtapConstants.InitPacketMask) == CtapConstants.CtapHidInit)
            {
                InitRequestCount++;
                _lastInitRequest = snapshot;
                _initResponseSent = false;
            }

            if (ThrowOnNextSend)
            {
                ThrowOnNextSend = false;
                throw new IOException("Scripted send failure.");
            }

            return Task.CompletedTask;
        }

        public void ClearCapturedPackets()
        {
            RetainedSentPackets.Clear();
            SentPacketSnapshots.Clear();
        }

        public Task<ReadOnlyMemory<byte>> ReceiveAsync(CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();
            if (HoldNextReceive)
            {
                HoldNextReceive = false;
                PendingReceive.TrySetResult();
                return _heldRead.Task;
            }
            if (!_initResponseSent)
            {
                _initResponseSent = true;
                return Task.FromResult<ReadOnlyMemory<byte>>(CreateInitResponse());
            }

            var packet = _responsePackets.Dequeue();
            OnResponseDequeued?.Invoke(packet);
            return Task.FromResult<ReadOnlyMemory<byte>>(packet);
        }

        public void Dispose()
        {
            IsDisposed = true;
        }

        public ValueTask DisposeAsync() => ValueTask.CompletedTask;

        public void RequestTerminalWake()
        {
            TerminalWakeCount++;
            _heldRead.TrySetException(new InvalidOperationException("Terminal wake"));
        }

        private byte[] CreateInitResponse()
        {
            if (_lastInitRequest is null)
                throw new InvalidOperationException("INIT request was not sent.");

            var payload = new byte[17];
            _lastInitRequest.AsSpan(CtapConstants.InitHeaderSize, CtapConstants.NonceSize).CopyTo(payload);
            BinaryPrimitives.WriteUInt32BigEndian(payload.AsSpan(8), TestChannelId);
            payload[12] = 2;
            payload[13] = 5;
            payload[14] = 8;
            payload[15] = 0;
            payload[16] = 0;
            return CreateInitPacket(CtapConstants.BroadcastChannelId, CtapConstants.CtapHidInit, payload);
        }
    }

    private sealed class RecordingUserPresencePrompt(
        Exception? requestedException = null,
        Exception? resolvedException = null) : IUserPresencePrompt
    {
        public List<UserPresenceContext> Requested { get; } = [];
        public List<(UserPresenceContext Context, UserPresenceOutcome Outcome, CancellationToken CancellationToken)>
            Resolved
        { get; } = [];

        public ValueTask OnUserPresenceRequestedAsync(
            UserPresenceContext context,
            CancellationToken cancellationToken)
        {
            Requested.Add(context);
            if (requestedException is not null)
            {
                throw requestedException;
            }

            return default;
        }

        public ValueTask OnUserPresenceResolvedAsync(
            UserPresenceContext context,
            UserPresenceOutcome outcome,
            CancellationToken cancellationToken)
        {
            Resolved.Add((context, outcome, cancellationToken));
            return resolvedException is null
                ? default
                : ValueTask.FromException(resolvedException);
        }
    }

    private sealed class RecordingLogger : ILogger<FidoHidProtocol>
    {
        public List<Exception?> Exceptions { get; } = [];
        public List<string> Events { get; } = [];

        public IDisposable? BeginScope<TState>(TState state)
            where TState : notnull => null;

        public bool IsEnabled(LogLevel logLevel) => true;

        public void Log<TState>(
            LogLevel logLevel,
            EventId eventId,
            TState state,
            Exception? exception,
            Func<TState, Exception?, string> formatter)
        {
            Events.Add(formatter(state, exception));
            if (state is IEnumerable<KeyValuePair<string, object?>> values)
            {
                foreach (var value in values)
                    Events.Add($"{value.Key}={value.Value}");
            }
            if (exception is not null)
                Events.Add(exception.ToString());
            Exceptions.Add(exception);
        }
    }
}

