///     swaps; without this, the two could race under parallel test-collection execution.
/// </remarks>
[Collection(CryptographyProvidersCollection.Name)]
public class Scp11X963KdfTests
{
    [Fact]
    public void TestDeriveKeyMaterial_WithTestVectors()
    {
        // Use test vectors from ansx963_2001.rsp (COUNT = 0, 128-bit output)
        var z = Convert.FromHexString("96c05619d56c328ab95fe84b18264b08725b85e33fd34f08");
        var sharedInfo = ReadOnlySpan<byte>.Empty; // Empty SharedInfo
        var expected = Convert.FromHexString("443024c3dae66b95e6f5670601558f71");

        var result = X963Kdf.DeriveKeyMaterial(z, sharedInfo, 16);

        Assert.Equal(expected, result);
    }

    [Fact]
    public void TestGetSharedSecret()
    {
        // Mock EC keys for testing GetSharedSecret
        var pkSdEcka = CreateTestSdPublicKey();
        var ephemeralOceEcka = CreateTestOceEphemeralPrivateKey();
        var skOceEcka = CreateTestOceStaticPrivateKey();
        var epkSdEckaTlvBytes = CreateTestEpkSdEckaTlv();

        var sharedSecret = Scp11X963Kdf.GetSharedSecret(ephemeralOceEcka, skOceEcka, pkSdEcka, epkSdEckaTlvBytes);

        // Expected shared secret: concatenation of ka1 and ka2
        // This case asserts only the combined width, not independently expected shared-secret bytes.
        Assert.Equal(64, sharedSecret.Length); // 32 bytes each for P-256
    }

    [Fact]
    public void GetSharedSecret_WhenSecondPrivateKeyExportFails_ZeroesFirstPrivateValue()
    {
        using var ephemeralOceKey = ECDiffieHellman.Create(ECCurve.NamedCurves.nistP256);
        using var staticOceKey = ECDiffieHellman.Create(ECCurve.NamedCurves.nistP256);
        using var staticSdKey = ECDiffieHellman.Create(ECCurve.NamedCurves.nistP256);
        using ECDiffieHellmanPublicKey staticSdPublicKey = staticSdKey.PublicKey;
        ReadOnlyMemory<byte> ephemeralSdPublicKey = CreateTestEpkSdEckaTlv();
        byte[]? firstPrivateValue = null;
        var exportCalls = 0;

        Assert.Throws<CryptographicException>(() => Scp11X963Kdf.GetSharedSecret(
            ephemeralOceKey,
            staticOceKey,
            staticSdPublicKey,
            ephemeralSdPublicKey,
            key =>
            {
                if (++exportCalls == 2)
                {
                    throw new CryptographicException("Injected second private-key export failure.");
                }

                ECParameters parameters = key.ExportParameters(true);
                firstPrivateValue = parameters.D;
                return parameters;
            }));

        byte[] observedPrivateValue = Assert.IsType<byte[]>(firstPrivateValue);
        Assert.All(observedPrivateValue, value => Assert.Equal(0, value));
    }

    [Fact]
    public void TestGetKeyAgreementData()
    {
        var epkSdEckaTlvBytes = CreateTestEpkSdEckaTlv();
        var hostAuthenticateTlvBytes = CreateTestHostAuthenticateTlv();

        var keyAgreementData = Scp11X963Kdf.GetKeyAgreementData(hostAuthenticateTlvBytes, epkSdEckaTlvBytes);

        // Should be concatenation of hostAuthenticateTlvBytes and epkSdEckaTlvBytes
