using Yubico.YubiKit.Core.UnitTests.Protocols.SmartCard.Apdu.Fakes;

namespace Yubico.YubiKit.Core.UnitTests.Protocols.SmartCard.Scp;

/// <summary>
///     Tests firmware validation in the internal PC/SC SCP initialization capability.
///     Verifies that appropriate NotSupportedException is thrown for unsupported firmware versions.
/// </summary>
/// <remarks>
///     Shares <see cref="CryptographyProvidersCollection"/> because the SCP11b "proceeds past the firmware
///     check" tests reach <c>ScpState.Scp11InitAsync</c>, which calls
///     <c>CryptographyProviders.EcdhPrimitivesCreator().GenerateKeyPair(...)</c> before any APDU is
///     transmitted (SCP11b skips the SCP11a/c-only PERFORM SECURITY OPERATION step). Without this,
///     these tests could race against
///     <see cref="Yubico.YubiKit.Core.UnitTests.Cryptography.CryptographyProviderExtensionTests"/>,
///     which temporarily swaps that same static.
/// </remarks>
[Collection(CryptographyProvidersCollection.Name)]
public class PcscProtocolScpInitializationTests
{
    private readonly FakeSmartCardConnection _fakeConnection = new();
    private readonly NullLogger<PcscProtocol> _logger = NullLogger<PcscProtocol>.Instance;

    [Fact]
    public async Task InitializeScpAsync_Scp03_FirmwareBelow530_ThrowsNotSupportedException()
    {
        // Arrange
        var protocol = new PcscProtocol(_fakeConnection, default, _logger);
        protocol.Configure(new FirmwareVersion(5, 2, 9)); // Just below 5.3.0

        // Act & Assert
        var ex = await Assert.ThrowsAsync<NotSupportedException>(async () =>
            await protocol.InitializeScpAsync(Scp03KeyParameters.Default, TestContext.Current.CancellationToken));

        Assert.Contains("SCP03", ex.Message);
        Assert.Contains("5.3.0", ex.Message);
    }

    [Fact]
    public async Task InitializeScpAsync_Scp03_FirmwareExactly530_Proceeds()
    {
        // Arrange
        var protocol = new PcscProtocol(_fakeConnection, default, _logger);
        protocol.Configure(new FirmwareVersion(5, 3)); // Exactly 5.3.0

        // Act & Assert
        // Should proceed to initialization (will fail because fake connection doesn't respond,
        // but we're only testing that firmware check passes)
        var ex = await Assert.ThrowsAnyAsync<Exception>(async () =>
            await protocol.InitializeScpAsync(Scp03KeyParameters.Default, TestContext.Current.CancellationToken));

        // Should NOT be NotSupportedException about firmware
        Assert.IsNotType<NotSupportedException>(ex);
    }

    [Fact]
    public async Task InitializeScpAsync_Scp03_FirmwareAbove530_Proceeds()
    {
        // Arrange
        var protocol = new PcscProtocol(_fakeConnection, default, _logger);
        protocol.Configure(new FirmwareVersion(5, 4, 3)); // Above 5.3.0

        using var staticKeys = StaticKeys.GetDefaultKeys();
        var keyParams = new Scp03KeyParameters(new KeyReference(0x01, 0xFF), staticKeys);

        // Act & Assert
        var ex = await Assert.ThrowsAnyAsync<Exception>(async () =>
            await protocol.InitializeScpAsync(keyParams, TestContext.Current.CancellationToken));

        // Should NOT be NotSupportedException about firmware
        Assert.IsNotType<NotSupportedException>(ex);
    }

    [Fact]
    public async Task InitializeScpAsync_Scp11_FirmwareBelow572_ThrowsNotSupportedException()
    {
        // Arrange
        var protocol = new PcscProtocol(_fakeConnection, default, _logger);
        protocol.Configure(new FirmwareVersion(5, 7, 1)); // Just below 5.7.2

        // Create minimal SCP11b params (simplest variant)
        using var ecdh = ECDiffieHellman.Create();

        var publicKey = ECPublicKey.CreateFromParameters(ecdh.PublicKey.ExportParameters());
        var keyParams = new Scp11KeyParameters(new KeyReference(ScpKid.SCP11b, 0xFF), publicKey);

        // Act & Assert
        var ex = await Assert.ThrowsAsync<NotSupportedException>(async () =>
            await protocol.InitializeScpAsync(keyParams, TestContext.Current.CancellationToken));

        Assert.Contains("SCP11", ex.Message);
        Assert.Contains("5.7.2", ex.Message);
    }

    [Fact]
    public async Task InitializeScpAsync_Scp11_FirmwareExactly572_Proceeds()
    {
        // Arrange
        var protocol = new PcscProtocol(_fakeConnection, default, _logger);
        protocol.Configure(new FirmwareVersion(5, 7, 2)); // Exactly 5.7.2

        using var ecdh = ECDiffieHellman.Create();

        var publicKey = ECPublicKey.CreateFromParameters(ecdh.PublicKey.ExportParameters());
        var keyParams = new Scp11KeyParameters(
            new KeyReference(ScpKid.SCP11b, 0xFF),
            publicKey
        );

        // Act & Assert
        var ex = await Assert.ThrowsAnyAsync<Exception>(async () =>
            await protocol.InitializeScpAsync(keyParams, TestContext.Current.CancellationToken));

        // Should NOT be NotSupportedException about firmware
        Assert.IsNotType<NotSupportedException>(ex);
    }

    [Fact]
    public async Task InitializeScpAsync_Scp11_FirmwareAbove572_Proceeds()
    {
        // Arrange
        var protocol = new PcscProtocol(_fakeConnection, default, _logger);
        protocol.Configure(new FirmwareVersion(5, 8)); // Above 5.7.2

        using var ecdh = ECDiffieHellman.Create();
        var publicKey = ECPublicKey.CreateFromParameters(ecdh.PublicKey.ExportParameters());

        var keyParams = new Scp11KeyParameters(
            new KeyReference(ScpKid.SCP11b, 0xFF),
            publicKey
        );

        // Act & Assert
        var ex = await Assert.ThrowsAnyAsync<Exception>(async () =>
            await protocol.InitializeScpAsync(keyParams, TestContext.Current.CancellationToken));

        // Should NOT be NotSupportedException about firmware
        Assert.IsNotType<NotSupportedException>(ex);
    }

    [Fact]
    public async Task InitializeScpAsync_Scp03_UnknownFirmware_Proceeds()
    {
        // Arrange
        var protocol = new PcscProtocol(_fakeConnection, default, _logger);
        // Don't call Configure - firmware version remains null

        using var staticKeys = StaticKeys.GetDefaultKeys();
        var keyParams = new Scp03KeyParameters(new KeyReference(0x01, 0xFF), staticKeys);

        // Act & Assert
        // Null firmware fails ScpInitializer's configured-processor admission before the support branch.
        // This broad exception assertion does not establish that the branch or handshake was reached.
        var ex = await Assert.ThrowsAnyAsync<Exception>(async () =>
            await protocol.InitializeScpAsync(keyParams, TestContext.Current.CancellationToken));

        // The conditional message assertion below does not require the current ArgumentException outcome.
        if (ex is NotSupportedException notSupported)
            // For a NotSupportedException, it only excludes this firmware threshold from the message.
            Assert.DoesNotContain("5.3.0", notSupported.Message);
    }

    [Fact]
    public async Task InitializeScpAsync_Scp03_AlphaBetaFirmware_Proceeds()
    {
        // Arrange
        var protocol = new PcscProtocol(_fakeConnection, default, _logger);
        protocol.Configure(new FirmwareVersion(0, 0, 1));

        using var staticKeys = StaticKeys.GetDefaultKeys();
        var keyParams = new Scp03KeyParameters(new KeyReference(0x01, 0xFF), staticKeys);

        // Act & Assert
        var ex = await Assert.ThrowsAnyAsync<Exception>(async () =>
            await protocol.InitializeScpAsync(keyParams, TestContext.Current.CancellationToken));

        Assert.IsNotType<NotSupportedException>(ex);
    }

    [Fact]
    public async Task InitializeScpAsync_Scp11_UnknownFirmware_Proceeds()
    {
        // Arrange
        var protocol = new PcscProtocol(_fakeConnection, default, _logger);
        // Don't call Configure - firmware version remains null

        using var ecdh = ECDiffieHellman.Create();
        var publicKey = ECPublicKey.CreateFromParameters(ecdh.PublicKey.ExportParameters());

        var keyParams = new Scp11KeyParameters(
            new KeyReference(ScpKid.SCP11b, 0xFF),
            publicKey
        );

        // Null firmware fails configured-processor admission before the SCP11 support branch or handshake.
        // The broad exception assertion below does not require that current ArgumentException outcome.
        // Act & Assert
        var ex = await Assert.ThrowsAnyAsync<Exception>(async () =>
            await protocol.InitializeScpAsync(keyParams, TestContext.Current.CancellationToken));

        // This conditional check only excludes the firmware threshold if the exception has this type.
        if (ex is NotSupportedException notSupported) Assert.DoesNotContain("5.7.2", notSupported.Message);
    }
}

