    ///     An alpha or beta PIV version falls back to AES-192, not Triple-DES, when management key
    ///     metadata is unavailable.
    /// </summary>
    /// <remarks>
    ///     A major-zero fixture selects the SDK's optimistic development-version policy and AES-192
    ///     fallback. These synthetic bytes establish no physical firmware minimum or installed key type.
    ///     Available management metadata takes precedence. See <see cref="FirmwareVersion.IsAlphaOrBeta" />.
    /// </remarks>
    [Theory]
    [InlineData(0, 0, 0)]
    [InlineData(0, 0, 1)]
    [InlineData(0, 9, 9)]
    public async Task CreateAsync_WhenAlphaFirmwareManagementMetadataUnavailable_UsesAes192Fallback(
        int major,
        int minor,
        int patch)
    {
        var connection = new RecordingSmartCardConnection(
            OkResponse(),
            [(byte)major, (byte)minor, (byte)patch, 0x90, 0x00],
            [0x6A, 0x88]);

        await using var session = await PivSession.CreateAsync(
            connection,
            cancellationToken: TestContext.Current.CancellationToken);

        Assert.Equal(KeyType.Aes192, session.ManagementKeyType);
    }

    /// <summary>
    ///     A released firmware below 5.7 still falls back to Triple-DES.
    /// </summary>
    [Theory]
    [InlineData(4, 3, 0)]
    [InlineData(5, 6, 9)]
    public async Task CreateAsync_WhenPre57FirmwareManagementMetadataUnavailable_UsesTripleDesFallback(
        int major,
        int minor,
        int patch)
    {
        var connection = new RecordingSmartCardConnection(
            OkResponse(),
            [(byte)major, (byte)minor, (byte)patch, 0x90, 0x00],
            [0x6A, 0x88]);

        await using var session = await PivSession.CreateAsync(
            connection,
            cancellationToken: TestContext.Current.CancellationToken);

        Assert.Equal(KeyType.TripleDes, session.ManagementKeyType);
    }

