using Yubico.YubiKit.Core.Abstractions;

namespace Yubico.YubiKit.Oath;

/// <summary>
///     Interface for interacting with the OATH application on a YubiKey.
/// </summary>
/// <remarks>
///     Inherited IsAuthenticated records Core SCP setup, not OATH password validation or ongoing channel
///     health. IsLocked and IsPasswordProtected describe this session's observed applet state. Cached
///     metadata getters can retain historical values after disposal; operations refuse a terminal session.
///     Await complete public tasks before disposal or input cleanup. Aggregate followups, authentication
///     retry and user-presence callbacks extend beyond Core's individual guarded exchanges. Keep borrowed
///     inputs and callback/prompt resources alive until those tasks finish, without reentrant disposal.
/// </remarks>
public interface IOathSession : IApplicationSession
{
    /// <summary>
    ///     Gets this session's device identifier, computed as <c>Base64(SHA256(salt)[:16])</c> with padding stripped.
    ///     A fresh session after factory reset reads the new salt and identifier; this cached value is not refreshed.
    /// </summary>
    string DeviceId { get; }

    /// <summary>
    ///     Gets the raw salt bytes from the OATH applet SELECT response.
    /// </summary>
    /// <remarks>
    ///     Borrows session-owned storage until disposal, which clears existing views. Copy only when
    ///     independent storage is needed. Successful RESET ends the session; create a fresh session for
    ///     the new salt and identity rather than reading historical cached state from this one.
    /// </remarks>
    ReadOnlyMemory<byte> Salt { get; }

    /// <summary>
    ///     Gets whether the current session must be unlocked before performing protected operations.
    /// </summary>
    /// <remarks>
    ///     <para>
    ///         When a password is configured, the session starts locked. Call <see cref="ValidateAsync" />
    ///         to unlock it. Successful validation sets this property to <see langword="false" />
    ///         without removing the password.
    ///     </para>
    ///     <para>To check whether a password is configured, use <see cref="IsPasswordProtected" />.</para>
    /// </remarks>
    bool IsLocked { get; }

    /// <summary>
    ///     Gets whether the OATH applet has a password configured, independent of whether the
    ///     current session has already been unlocked via <see cref="ValidateAsync" />.
    /// </summary>
    /// <remarks>
    ///     Reflects SELECT and successful password changes in this session, not a fresh device query.
    ///     Unlike <see cref="IsLocked" />, which becomes <see langword="false" /> once the current
    ///     session successfully validates, this property remains <see langword="true" /> after validation.
    ///     Use this to distinguish "no password configured" from "password already unlocked this session" —
    ///     for example, to decide whether a "remove password" UI action should be shown, or whether
    ///     a key-change flow needs to prompt for the current password.
    /// </remarks>
    bool IsPasswordProtected { get; }

    /// <summary>
    ///     Lists all credentials stored on the device.
    /// </summary>
    /// <remarks>
    ///     A TOTP credential with a recognized ASCII-digit period prefix that is zero or exceeds
    ///     <see cref="int.MaxValue" /> is omitted and logged at warning level. This does not imply
    ///     general validation of raw credential IDs.
    /// </remarks>
    /// <exception cref="Core.BadResponseException">
    ///     A recognized LIST entry lacks its type/algorithm byte or a nonempty credential ID.
    /// </exception>
    Task<IReadOnlyList<Credential>> ListCredentialsAsync(CancellationToken cancellationToken = default);

    /// <summary>
    ///     Adds a credential or replaces an existing credential with the same raw credential ID.
    /// </summary>
    /// <remarks>
    ///     <para>
    ///         The raw ID is produced by <see cref="CredentialData.GetId" />. The SDK sends PUT without
    ///         checking whether that ID already exists on the device.
    ///         Before sending PUT or processing the secret, the SDK validates request numbers, nonempty secret
    ///         material, and an identity that round-trips through the host naming convention within 64 UTF-8 bytes,
    ///         including issuer, separators, and any period prefix. Failed preflight sends no PUT.
    ///     </para>
    ///     <para>
    ///         Borrows <paramref name="credentialData" /> until the operation completes. PUT uses independent
    ///         temporary secret storage and does not clear the credential's owned seed, including on failure.
    ///         The same instance can be used for authentication retry; dispose it only after all uses complete.
    ///     </para>
    /// </remarks>
    /// <exception cref="ArgumentException">
    ///     The secret is empty, the name is empty, the issuer is empty rather than null, the complete ID exceeds
    ///     64 UTF-8 bytes, or encoding/parsing the ID changes the supplied name, issuer, or TOTP period.
    /// </exception>
    /// <exception cref="ArgumentOutOfRangeException">
    ///     Digits are outside 6 through 8, the TOTP period is not positive, the HOTP counter is negative,
    ///     or the hash algorithm is unsupported. HOTP counters support 0 through <see cref="int.MaxValue" />.
    /// </exception>
    Task PutCredentialAsync(CredentialData credentialData,
        CancellationToken cancellationToken = default);

    /// <summary>
    ///     Deletes a credential from the device.
    /// </summary>
    /// <exception cref="ArgumentException">
    ///     <paramref name="credential" /> was read from a different device (its <see cref="Credential.DeviceId" />
    ///     is not this session's <see cref="DeviceId" />). Nothing is sent.
    /// </exception>
    Task DeleteCredentialAsync(Credential credential, CancellationToken cancellationToken = default);

    /// <summary>
    ///     Renames a credential on the device. Requires firmware 5.3.1+.
    /// </summary>
    /// <returns>A new credential with the new identity; the supplied credential remains unchanged.</returns>
    /// <remarks>
    ///     Borrows <paramref name="credential" /> without modifying its ID. Before sending RENAME, the SDK
    ///     requires a nonempty new name, a null or nonempty issuer, and a complete ID of at most 64 UTF-8 bytes,
    ///     including issuer, separators, and any period prefix. Encoding and parsing that ID must preserve the
    ///     supplied name, issuer, and existing TOTP period. Colons and slashes are allowed when they round-trip.
    /// </remarks>
    /// <exception cref="ArgumentException">
    ///     <paramref name="credential" /> was read from a different device (its <see cref="Credential.DeviceId" />
    ///     is not this session's <see cref="DeviceId" />), or the new identity fails the size or round-trip
    ///     requirements. No RENAME is sent.
    /// </exception>
