    private static void AssertValidCrc(byte[] config)
    {
        Assert.Equal(YubiOtpConstants.ConfigSize, config.Length);
        Assert.True(ChecksumUtils.CheckCrc(config, YubiOtpConstants.ConfigSize));
    }


    [Fact]
