        NonInteractiveSelection nonInteractiveSelection,
        IAnsiConsole console,
        Func<CancellationToken, Task<IReadOnlyList<IYubiKey>>> findAll,
        Func<IYubiKey, CancellationToken, Task<DeviceInfo?>> readInfo,
