        _mockBackend.GetAssertionAsync(
            Arg.Any<BackendGetAssertionRequest>(),
            Arg.Any<CancellationToken>())
            .Returns<GetAssertionResponse>(x => throw new CtapException(CtapStatus.NoCredentials));

