        await _mockBackend.DidNotReceive().GetPinUvTokenAsync(
            Arg.Any<PinUvAuthMethod>(), Arg.Any<PinUvAuthTokenPermissions>(), Arg.Any<string?>(),
            Arg.Any<ReadOnlyMemory<byte>?>(), Arg.Any<CancellationToken>());
