    private void ArrangePinTokenAcquisition(TestPinUvAuthProtocol protocol)
    {
        _mockBackend.GetCachedInfoAsync(Arg.Any<CancellationToken>())
            .Returns(MockCtap2Responses.CreateMockAuthenticatorInfo(
                clientPinSupported: true, extensions: MockCtap2Responses.AllKnownExtensions, largeBlobsSupported: true));

        _mockBackend.GetPinUvTokenAsync(
            PinUvAuthMethod.Pin,
            PinUvAuthTokenPermissions.GetAssertion,
            "example.com",
            Arg.Any<ReadOnlyMemory<byte>?>(),
            Arg.Any<CancellationToken>())
            .Returns(_ => new PinUvAuthTokenSession(protocol, TokenBufferAssert.CreateSentinelToken()));
    }

    /// <summary>
    /// Arranges an authenticator with a PIN set and hands the client a token session that owns
    /// <paramref name="token"/>, so the test can inspect that buffer after the ceremony.
    /// </summary>
    /// <remarks>
    /// The session does not copy the array, so <paramref name="token"/> is the session's owned
    /// buffer and is also the buffer <c>ClientPin</c> would have returned in production.
    /// </remarks>
    private void ArrangePinTokenAcquisition(byte[] token)
    {
        _mockBackend.GetCachedInfoAsync(Arg.Any<CancellationToken>())
            .Returns(MockCtap2Responses.CreateMockAuthenticatorInfo(clientPinSupported: true));

        _mockBackend.GetPinUvTokenAsync(
            PinUvAuthMethod.Pin,
            PinUvAuthTokenPermissions.GetAssertion,
            "example.com",
            Arg.Any<ReadOnlyMemory<byte>?>(),
            Arg.Any<CancellationToken>())
            .Returns(_ => new PinUvAuthTokenSession(new TestPinUvAuthProtocol(), token));
    }

    /// <summary>
    /// Guards the zeroing assertions against passing for the wrong reason: a ceremony that never
    /// minted a token would never have had a buffer to clear.
    /// </summary>
    private async Task AssertTokenWasAcquired() =>
        await _mockBackend.Received(1).GetPinUvTokenAsync(
            PinUvAuthMethod.Pin,
            PinUvAuthTokenPermissions.GetAssertion,
            "example.com",
            Arg.Any<ReadOnlyMemory<byte>?>(),
            Arg.Any<CancellationToken>());

    private static PublicKeyCredentialRequestOptions CreateUvRequiredOptions() => new()
    {
        Challenge = RandomNumberGenerator.GetBytes(32),
        RpId = "example.com",
        UserVerification = UserVerificationPreference.Required
    };

    [Fact(Timeout = 5000)]
    public async Task MatchedCredential_SelectAsync_HonorsCancellationToken()
    {
        // An internal slow factory tests waiting semantics; production matches already hold built responses.
        var credentialId = RandomNumberGenerator.GetBytes(32);
        var tcs = new TaskCompletionSource<AuthenticationResponse>();

        var rawAuthData = MockCtap2Responses.BuildAuthData();
        var mockResponse = new AuthenticationResponse
        {
            CredentialId = credentialId,
            RawAuthenticatorData = rawAuthData,
            Signature = RandomNumberGenerator.GetBytes(64),
            SignCount = 1,
            ClientData = WebAuthnClientData.Create("webauthn.get", RandomNumberGenerator.GetBytes(32), _origin, null, null),
            ClientExtensionResults = null,
            AuthenticatorData = WebAuthnAuthenticatorData.Decode(rawAuthData),
            User = null
        };

        var match = new MatchedCredential(
            credentialId,
            user: null,
            responseFactory: _ => tcs.Task);

        // Act - Call with already-cancelled token (factory hasn't completed yet)
        using var cts = new CancellationTokenSource();
        cts.Cancel();
        await Assert.ThrowsAnyAsync<OperationCanceledException>(() => match.SelectAsync(cts.Token));

        // Complete the factory
        tcs.SetResult(mockResponse);

        // Verify calling again with None works (lazy is now complete)
        var response = await match.SelectAsync(CancellationToken.None);
        Assert.NotNull(response);
        Assert.Equal(credentialId, response.CredentialId.ToArray());
    }
}

